import { isRecord } from "./event-envelope.js";

export const SOCKET_CONTROL_TYPES = new Set([
  "subscribe",
  "status",
  "publish",
  "event.get",
  "app.input.admit",
  "app.conversation.get",
  "app.tasks.list",
  "app.task.get",
  "app.task.retry",
  "app.task.resolve",
  "apps.list",
  "tasks.list",
  "task.get",
  "task.close",
  "task.reopen",
  "task.cancel",
  "project.actions.describe",
  "project.action.invoke",
]);

export type SocketFrame =
  | {
      kind: "control";
      command:
        | "subscribe"
        | "status"
        | "publish"
        | "event.get"
        | "app.input.admit"
        | "app.conversation.get"
        | "app.tasks.list"
        | "app.task.get"
        | "app.task.retry"
        | "app.task.resolve"
        | "apps.list"
        | "tasks.list"
        | "task.get"
        | "task.close"
        | "task.reopen"
        | "task.cancel"
        | "project.actions.describe"
        | "project.action.invoke";
      frame: Record<string, unknown>;
    }
  | { kind: "event"; command: string; event: Record<string, unknown> }
  | { kind: "error"; command: unknown; message: string };

export function isSocketCommandType(type: string): boolean {
  return type.startsWith("trigger.");
}

function isCanonicalEventType(type: string): boolean {
  return type.includes(".") && !isSocketCommandType(type);
}

function canonicalEventError(event: Record<string, unknown>): string | null {
  const type = event.type;
  if (typeof type !== "string") return null;
  if (!isCanonicalEventType(type)) return null;
  if (!isRecord(event.data)) return `Canonical event '${type}' requires object field 'data'`;
  if (typeof event.source !== "string" || !event.source.trim())
    return `Canonical event '${type}' requires string field 'source'`;
  if (typeof event.owner !== "string" || !event.owner.trim())
    return `Canonical event '${type}' requires string field 'owner'`;
  return null;
}

function socketEvent(command: string, event: Record<string, unknown>): SocketFrame {
  const message = canonicalEventError(event);
  return message ? { kind: "error", command, message } : { kind: "event", command, event };
}

export function normalizeSocketFrame(frame: Record<string, unknown>): SocketFrame {
  const cmdType = frame.type;
  if (typeof cmdType !== "string" || !cmdType.trim()) {
    return { kind: "error", command: cmdType ?? null, message: `Missing or invalid event type: ${String(cmdType)}` };
  }

  if (SOCKET_CONTROL_TYPES.has(cmdType)) {
    return {
      kind: "control",
      command: cmdType as
        | "subscribe"
        | "status"
        | "publish"
        | "event.get"
        | "app.input.admit"
        | "app.conversation.get"
        | "app.tasks.list"
        | "app.task.get"
        | "app.task.retry"
        | "app.task.resolve"
        | "apps.list"
        | "tasks.list"
        | "task.get"
        | "task.close"
        | "task.reopen"
        | "task.cancel"
        | "project.actions.describe"
        | "project.action.invoke",
      frame,
    };
  }

  if (!isCanonicalEventType(cmdType) && !isSocketCommandType(cmdType)) {
    return { kind: "error", command: cmdType, message: `Unsupported socket frame type: ${cmdType}` };
  }

  return socketEvent(cmdType, frame);
}

if (normalized.kind === "control" && normalized.command === "app.task.retry") {
  const appId = typeof frame.appId === "string" ? frame.appId.trim() : "";
  const taskId = typeof frame.taskId === "string" ? frame.taskId.trim() : "";
  const expectedGeneration = frame.expectedGeneration;
  if (
    !appId ||
    !taskId ||
    typeof expectedGeneration !== "number" ||
    !Number.isSafeInteger(expectedGeneration) ||
    expectedGeneration < 1 ||
    !publishEvent ||
    !getTask
  ) {
    writeFrame(socket, {
      type: "error",
      command: normalized.command,
      message: !appId
        ? "appId is required"
        : !taskId
          ? "taskId is required"
          : typeof expectedGeneration !== "number" ||
              !Number.isSafeInteger(expectedGeneration) ||
              expectedGeneration < 1
            ? "expectedGeneration must be a positive integer"
            : "App Task retry is unavailable",
    });
    continue;
  }
  try {
    const task = getTask({ appId, taskId }) as Record<string, unknown> | null;
    if (!task) throw new Error(`Task ${appId}/${taskId} was not found`);
    if (task.generation !== expectedGeneration) {
      throw new Error(
        `Task ${appId}/${taskId} generation changed: expected ${expectedGeneration}, current ${String(task.generation)}`,
      );
    }
    if (!Number.isSafeInteger(task.resourceVersion) || Number(task.resourceVersion) < 1) {
      throw new Error(`Task ${appId}/${taskId} has no valid resource version`);
    }
    const receipt = publishEvent({
      type: "app.task.retry.requested",
      target: { appId, taskId },
      data: {
        expectedGeneration,
        expectedResourceVersion: Number(task.resourceVersion),
      },
      idempotencyKey: `app-task-retry:${appId}:${taskId}:${expectedGeneration}:${Number(task.resourceVersion)}`,
    });
    if (receipt.delivery !== "accepted") {
      throw new Error(`Task ${appId}/${taskId} retry was recorded but not accepted; read the Task and retry`);
    }
    writeFrame(socket, {
      type: "ok",
      command: normalized.command,
      receipt,
    });
  } catch (error) {
    writeFrame(socket, {
      type: "error",
      command: normalized.command,
      message: error instanceof Error ? error.message : String(error),
    });
  }
  continue;
}

if (normalized.kind === "control" && normalized.command === "app.task.resolve") {
  const appId = typeof frame.appId === "string" ? frame.appId.trim() : "";

import type { AppInput } from "@may-agent/sdk";
import type { ExactTask } from "@may-agent/control/events";
export { taskRetryRequestedEvent, taskCloseRequestedEvent, taskCancelRequestedEvent, taskReopenRequestedEvent } from "@may-agent/control/events";
import { taskControlAction } from "./core/events/interface.js";
import { eventData, type AgentEvent, type EventBus, type SubscriberResult } from "./core/events/bus.js";

function positiveInteger(value: unknown, field: string): number {
  if (!Number.isSafeInteger(value) || Number(value) < 1) throw new Error(`${field} must be a positive integer`);
  return Number(value);
}

/** One synchronous, fenced mutation route shared by every external adapter. */
export function attachTaskControlEventRoute(
  bus: EventBus,
  access: {
    retryTask(input: ExactTask & { controlKey: string }): unknown;
    cancelTask(input: ExactTask & { reason: string; controlKey: string; decision: "human" | "app-policy" }): unknown;
    closeTask(input: ExactTask & { afterResult: string; reason: string; controlKey: string }): unknown;
    reopenTask(input: ExactTask & { reason: string; controlKey: string; input?: AppInput }): unknown;
  },
): () => void {
  return bus.subscribeDurableRoute(
    (event: AgentEvent): SubscriberResult => {
      const action = taskControlAction(event.type);
      if (!action) return;
      const data = eventData(event);
      const appId = typeof data.appId === "string" ? data.appId.trim() : "";
      const taskId = typeof data.taskId === "string" ? data.taskId.trim() : "";
      if (!appId || !taskId) throw new Error(`${event.type} requires an exact App Task target`);
      const expectedGeneration = positiveInteger(data.expectedGeneration, `${event.type} expectedGeneration`);
      const expectedResourceVersion = positiveInteger(
        data.expectedResourceVersion,
        `${event.type} expectedResourceVersion`,
      );
      const controlKey = typeof data.idempotencyKey === "string" ? data.idempotencyKey.trim() : "";
      if (!controlKey) throw new Error(`${event.type} requires an idempotency key`);

      const exact = { appId, taskId, generation: expectedGeneration, resourceVersion: expectedResourceVersion };
      switch (action) {
        case "reopen": {
          // The operator adapter is a trusted boundary. App/model payload claims
          // such as "humanRequested" do not authorize reopening.
          if (!("source" in event) || event.source !== "control-socket")
            throw new Error("Task reopening requires explicit operator control");
          const reason = typeof data.reason === "string" ? data.reason.trim() : "";
          if (!reason) throw new Error("Task reopening requires a reason");
          access.reopenTask({
            ...exact,
            reason,
            controlKey,
            ...(data.input !== undefined ? { input: data.input as AppInput } : {}),
          });
          break;
        }
        case "retry":
          access.retryTask({ ...exact, controlKey });
          break;
        case "close": {
          const reason = typeof data.reason === "string" ? data.reason.trim() : "";
          if (!reason) throw new Error(`${event.type} reason must be a non-empty string`);
          const afterResult = typeof data.afterResult === "string" ? data.afterResult.trim() : "";
          if (!afterResult) throw new Error("app.task.close.requested afterResult must be a non-empty attempt ID");
          access.closeTask({ ...exact, afterResult, reason, controlKey });
          break;
        }
        case "cancel": {
          const reason = typeof data.reason === "string" ? data.reason.trim() : "";
          if (!reason) throw new Error(`${event.type} reason must be a non-empty string`);
          access.cancelTask({
            ...exact,
            reason,
            controlKey,
            decision: "source" in event && event.source === "telegram" ? "human" : "app-policy",
          });
          break;
        }
        default: {
          const unsupported: never = action;
          throw new Error(`Unsupported Task control action: ${String(unsupported)}`);
        }
      }
      return { accepted: true, by: "task-control", route: "direct" };
    },
    { label: "task-control" },
  );
}

export type AppTaskRetryReceipt = {
  receiptId: string;
  action: "app.task.retry";
  disposition: "requeued";
  appId: string;
  taskId: string;
  generation: number;
  previousResourceVersion: number;
  resourceVersion: number;
  previousAttemptId: string;
  acceptedAt: string;
};

/**
 * Requeue one exact failed Task generation after an operator has reviewed its
 * retained input. The failed attempt remains immutable operational facts.
 * Execution failures restore their unconsidered input batch; an accepted
 * incomplete report has already advanced considered events and retains exact
 * unanswered input through inputWaits.
 */
export function retryFailedAppTask(
  config: AppTaskContext,
  input: {
    appId: string;
    taskId: string;
    expectedGeneration: number;
    expectedResourceVersion: number;
    controlKey?: string;
  },
): AppTaskRetryReceipt {
  if (config.resourceStore.isCancelled(input.taskId)) {
    throw new Error(`Cannot retry cancelled task ${input.appId}/${input.taskId}; create a new linked task`);
  }
  const priorControl = input.controlKey ? config.resourceStore.readControlReceipt(input.controlKey) : null;
  if (priorControl) {
    if (
      priorControl.action !== "retry" ||
      priorControl.appId !== input.appId ||
      priorControl.taskId !== input.taskId ||
      priorControl.expectedGeneration !== input.expectedGeneration ||
      priorControl.expectedResourceVersion !== input.expectedResourceVersion
    ) {
      throw new Error(`Task control key ${input.controlKey} was already used for a different operation`);
    }
    if (!priorControl.result || typeof priorControl.result !== "object" || Array.isArray(priorControl.result)) {
      throw new Error(`Task retry control receipt ${input.controlKey} has no valid result`);
    }
    return priorControl.result as AppTaskRetryReceipt;
  }
  const tree = config.resourceStore.readTaskContext({ taskIds: [input.taskId] });
  const resource = tree.resources?.[input.taskId];
  if (!resource) throw new Error(`Task ${input.appId}/${input.taskId} was not found`);
  if (resource.metadata.generation !== input.expectedGeneration) {
    throw new Error(
      `Task ${input.appId}/${input.taskId} generation changed: expected ${input.expectedGeneration}, current ${resource.metadata.generation}`,
    );
  }
  if (resource.metadata.resourceVersion !== input.expectedResourceVersion) {
    throw new Error(
      `Task ${input.appId}/${input.taskId} resource version changed: expected ${input.expectedResourceVersion}, current ${resource.metadata.resourceVersion}`,
    );
  }
  const cooling = resource.status.phase === "pending" && resource.status.executionRetryAt !== undefined;
  if (resource.status.phase !== "attention" && !cooling) {
    throw new Error(
      `Task ${input.appId}/${input.taskId} is not eligible for retry: phase is ${resource.status.phase}, expected a failed attempt awaiting retry`,
    );
  }
  const attempt = latestTaskAttempt(tree, input.taskId, input.expectedGeneration);
  const unsuccessful = attempt?.state === "failed" ||
    (attempt?.state === "completed" && attempt.acceptedResult?.state === "incomplete");
  if (!attempt || !unsuccessful || resource.status.currentAttemptId) {
    throw new Error(
      `Task ${input.appId}/${input.taskId} is not eligible for retry: its current generation has no completed failed attempt`,
    );
  }

  const previousResourceVersion = resource.metadata.resourceVersion;
  const acceptedAt = new Date().toISOString();
  const mutationScope = beginResourceMutationScopeForTasks(tree, [input.taskId]);
  if (attempt.state === "failed") restoreAttemptEvents(tree, input.taskId, resource, attempt, acceptedAt);
  touchResource(resource, {
    phase: "pending",
    executionFailures: undefined,
    executionRetryAt: undefined,
    observedGeneration: Math.max(0, resource.metadata.generation - 1),
    currentAttemptId: undefined,
  });
  const receipt: AppTaskRetryReceipt = {
    receiptId: randomUUID(),
    action: "app.task.retry",
    disposition: "requeued",
    appId: input.appId,
    taskId: input.taskId,
    generation: input.expectedGeneration,
    previousResourceVersion,
    resourceVersion: resource.metadata.resourceVersion,
    previousAttemptId: attempt.metadata.id,
    acceptedAt,
  };
  commitTaskMutation(config, tree, {
    resourceMutation: {
      ...finishResourceMutationScope(mutationScope, tree),
      ...(input.controlKey
        ? {
            controlReceipts: [
              {
                controlKey: input.controlKey,
                appId: input.appId,
                taskId: input.taskId,
                action: "retry" as const,
                expectedGeneration: input.expectedGeneration,
                expectedResourceVersion: input.expectedResourceVersion,
                appliedResourceVersion: resource.metadata.resourceVersion,
                appliedAt: Date.parse(acceptedAt),
                result: receipt,
              },
            ],
          }
        : {}),
    },
  });
  return receipt;
}
